<?php
use App\Services\LandingContentService as HeroCopy;
// Each composition owns its semantic wrapper; shared atoms read exactly the same data.
$heroCopy=static function()use($d):void{ ?><div class="nvl-hero-copy"><span class="nvl-eyebrow"><?= icon('map-pin',14) ?> <?= e($d['city']) ?> / <?= e($d['service']) ?></span><h1><?= e($d['title']) ?></h1><div class="nvl-hero-description"><?= HeroCopy::rich($d['summary']) ?></div><div class="nvl-actions"><a class="nvl-button" href="/iletisim"><?= e($d['cta_label']?:'Projenizi konuşalım') ?> <?= icon('arrow-up-right',17) ?></a><a class="nvl-secondary" href="#landing-content">Çözümleri keşfedin <?= icon('arrow-down',16) ?></a></div></div><?php };
$heroArt=static function()use($d):void{if($d['image']==='')return; ?><figure class="nvl-hero-art"><picture><?php if($d['mobile_image']!==''): ?><source media="(max-width:680px)" srcset="<?= e($d['mobile_image']) ?>"><?php endif; ?><img src="<?= e($d['image']) ?>" alt="<?= e($d['image_alt']) ?>" width="1536" height="1024" fetchpriority="high"></picture></figure><?php };
$heroPlace=static function()use($d):void{ ?><div class="nvl-place-card"><?= icon('map-pin',24) ?><span><strong><?= e($d['city']) ?></strong><small><?= e($d['service']) ?></small></span></div><?php };
$heroBoard=static function()use($d):void{ ?><div class="nvl-board" aria-label="Temsili çalışma planı"><span><?= icon('layers',16) ?> <?= e($d['service']) ?></span><strong>Projenize özel yol haritası</strong><div class="nvl-board-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div><small>Temsili arayüz · Sonuç veya ölçüm verisi değildir.</small></div><?php };
?>
<section class="nvl-hero nvl-hero-<?= e($heroVariant) ?> <?= $d['image']===''?'nvl-no-image':'' ?>">
<div class="nvl-container"><nav class="nvl-breadcrumb" aria-label="Konum"><a href="/">Ana Sayfa</a><span>/</span><a href="/hizmet-bolgeleri">Hizmet Bölgeleri</a><span>/</span><span><?= e($d['city']) ?></span></nav>
<?php switch($heroVariant):
case 'city': ?><div class="nvl-stage nvl-stage-city"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-city"><?php $heroArt();$heroPlace(); ?><div class="nvl-search-card"><?= icon('search',18) ?><span><?= e($d['city'].' · '.$d['service']) ?></span><?= icon('arrow-up-right',16) ?></div></div></div><?php break;
case 'night': ?><div class="nvl-stage nvl-stage-night"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-night"><div class="nvl-search-card"><?= icon('search',18) ?> <?= e($d['city'].' / '.$d['service']) ?></div><?php $heroArt();$heroBoard(); ?></div></div><?php break;
case 'growth': ?><div class="nvl-stage nvl-stage-growth"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-growth"><div class="nvl-orbit" aria-hidden="true"><?= icon('map-pin',34) ?></div><?php $heroArt();$heroPlace(); ?><span class="nvl-scene-note"><?= icon('target',18) ?> İhtiyaçtan stratejiye</span></div></div><?php break;
case 'glass': ?><div class="nvl-stage nvl-stage-glass"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-glass"><?php $heroArt();$heroBoard();$heroPlace(); ?></div></div><?php break;
case 'editorial': ?><div class="nvl-editorial-heading"><span>NETVERA / <?= e($d['city']) ?></span><span><?= e($d['service']) ?></span></div><div class="nvl-stage nvl-stage-editorial"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-editorial"><?php $heroArt(); ?><div class="nvl-editorial-caption"><?= icon('arrow-up-right',32) ?><span><?= e($d['city']) ?><small><?= e($d['service']) ?></small></span></div></div></div><?php break;
case 'local': ?><div class="nvl-stage nvl-stage-local"><div class="nvl-scene nvl-scene-local"><?php $heroArt();$heroPlace(); ?></div><?php $heroCopy(); ?></div><div class="nvl-local-strip"><?= icon('map-pin',18) ?><span><?= e($d['area']?:$d['city']) ?></span><span><?= e($mode) ?></span></div><?php break;
case 'conversion': ?><div class="nvl-stage nvl-stage-conversion"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-conversion"><?php $heroArt();$heroBoard(); ?><span class="nvl-scene-note"><?= icon('message-circle',18) ?> Kapsamı birlikte belirleyelim</span></div></div><?php break;
case 'saas': ?><div class="nvl-stage-saas"><?php $heroCopy(); ?><div class="nvl-saas-window"><div class="nvl-window-bar" aria-hidden="true"><i></i><i></i><i></i></div><div class="nvl-saas-scene"><?php $heroArt();$heroBoard(); ?></div></div></div><?php break;
case 'prism': ?><div class="nvl-stage nvl-stage-prism"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-prism"><span class="nvl-prism-ring" aria-hidden="true"></span><?php $heroArt();$heroPlace(); ?><span class="nvl-scene-note"><?= icon('sparkles',18) ?> Tek ekip, ortak vizyon</span></div></div><?php break;
default: ?><div class="nvl-stage nvl-stage-dimension"><?php $heroCopy(); ?><div class="nvl-scene nvl-scene-dimension"><div class="nvl-dimension-disc" aria-hidden="true"></div><?php $heroArt();$heroPlace(); ?><div class="nvl-dimension-target" aria-hidden="true"><?= icon('target',64) ?></div><span class="nvl-scene-note"><?= icon('layers',18) ?> Yazılım · Strateji · Tasarım</span></div></div><?php break; endswitch; ?>
<dl class="nvl-facts"><div><dt><?= icon('map-pin',17) ?> Hizmet bölgesi</dt><dd><?= e($d['area']?:trim($d['city'].', '.$d['province'],', ')) ?></dd></div><div><dt><?= icon('monitor',17) ?> Çalışma biçimi</dt><dd><?= e($mode) ?></dd></div><div><dt><?= icon('message-circle',17) ?> İlk adım</dt><dd>İhtiyaç ve kapsam görüşmesi</dd></div></dl>
</div></section>
